// Hand-authored — NOT generated by prism, and prism will not overwrite it
// (it only replaces files carrying its header).
//
// Every other wrapper in this package is a thin pass-through, because every
// other component needs nothing more. Virtualization does: the whole point is
// that rows don't exist until they're on screen, and only React can create a
// React row. A generated wrapper can pass the element's `renderItem` callback
// through, but that callback has to return DOM — so a React consumer building
// React rows cannot use it.
//
// This wrapper does what a React virtualizer does instead: it listens for the
// element's `arc-range-change`, keeps the visible range in state, and renders
// exactly those rows as light-DOM children carrying `slot="item-N"`. The
// element owns the scroll geometry; React owns the rows.
//
// Stays a .ts file (no JSX) deliberately: prism writes `VirtualList.ts` for
// this component, and a `.tsx` here would leave a generated `.ts` beside it
// exporting the same name. Nothing is lost — this package has no JSX anywhere.
import { createElement, useCallback, useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import '@arclux/arc-ui/virtual-list';

export interface VirtualListProps<T = unknown> {
  /** The full data array. Only the visible slice is rendered. */
  items: T[];
  /** Renders one row. Called only for rows currently on screen. */
  renderItem: (item: T, index: number) => ReactNode;
  /** Row height in pixels. Must match what actually renders. */
  itemHeight?: number;
  /** Rows rendered above and below the viewport, to cover fast scrolling. */
  overscan?: number;
  /** Called when the visible range changes. `end` is exclusive. */
  onRangeChange?: (range: { start: number; end: number }) => void;
  className?: string;
  style?: CSSProperties;
  id?: string;
}

type ListElement = HTMLElement & {
  items?: unknown[];
  visibleRange?: { start: number; end: number };
};

export function VirtualList<T = unknown>({
  items,
  renderItem,
  itemHeight = 40,
  overscan = 5,
  onRangeChange,
  ...rest
}: VirtualListProps<T>) {
  const ref = useRef<ListElement>(null);
  const [range, setRange] = useState({ start: 0, end: 0 });

  // `items` is an array, so it has to be set as a property — as an attribute it
  // would stringify.
  useEffect(() => {
    const el = ref.current;
    if (el) el.items = items;
  }, [items]);

  const onRange = useCallback((e: Event) => {
    const { start, end } = (e as CustomEvent).detail;
    setRange({ start, end });
    onRangeChange?.({ start, end });
  }, [onRangeChange]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.addEventListener('arc-range-change', onRange);
    // The element may have measured before this effect ran, in which case its
    // first range event is already spent.
    if (el.visibleRange) setRange({ ...el.visibleRange });
    return () => el.removeEventListener('arc-range-change', onRange);
  }, [onRange]);

  const rows: ReactNode[] = [];
  for (let i = range.start; i < Math.min(range.end, items.length); i++) {
    rows.push(createElement('div', { key: i, slot: `item-${i}` }, renderItem(items[i], i)));
  }

  return createElement('arc-virtual-list', { ref, 'item-height': itemHeight, overscan, ...rest }, rows);
}
